import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar"; // Component for the navigation bar
import Footer from "../Components/Footer"; // Component for the footer
import API_BASE_URL from "../config"; // Base URL for API requests
import "../styles/MyOrders.css"; // Import CSS styling for MyOrders page

// Functional component to display user's orders
const MyOrders = () => {
  // Retrieve user ID from session storage
  const userId = sessionStorage.getItem("userId");

  // State to store orders and users data
  const [orders, setOrders] = useState([]);
  const [users, setUsers] = useState([]);

  // useEffect hook to fetch orders and users data on component mount
  useEffect(() => {
    if (userId) {
      // Fetch orders associated with the logged-in user
      fetch(`${API_BASE_URL}/api/orders/user/${userId}`)
        .then((res) => res.json())
        .then(setOrders)
        .catch((err) => console.error("Failed to load orders", err));

      // Fetch user details
      fetch(`${API_BASE_URL}/api/users`)
        .then((res) => res.json())
        .then(setUsers)
        .catch((err) => console.error("Failed to load users", err));
    }
  }, [userId]);

  // Function to handle order cancellation
  const cancelOrder = async (orderId) => {
    // Confirmation before cancelling the order
    if (!window.confirm("Are you sure you want to cancel this order?")) return;

    const res = await fetch(`${API_BASE_URL}/api/orders/${orderId}`, {
      method: "DELETE",
    });

    if (res.ok) {
      // Remove the cancelled order from state
      setOrders(orders.filter((order) => order.id !== orderId));
    } else {
      alert("Failed to cancel order");
    }
  };

  // Helper function to get seller username by user ID
  const getSellerUsername = (user_id) => {
    const user = users.find((u) => u.id === user_id);
    return user ? user.username : "Unknown";
  };

  // JSX rendering user's order details
  return (
    <div className="orders-wrapper">
      <Navbar />
      <div className="orders-main">
        <h2>📦 My Orders</h2>
        {orders.length === 0 ? (
          <p>No orders placed yet.</p>
        ) : (
          orders.map((order) => {
            // Parse order items and shipping information
            const items = Array.isArray(order.items) ? order.items : JSON.parse(order.items);
            const shipping = typeof order.shipping_info === "string"
              ? JSON.parse(order.shipping_info)
              : order.shipping_info;

            return (
              <div className="order-card" key={order.id}>
                <div>
                  <strong>Order #{order.id}</strong> • {new Date(order.created_at).toLocaleString()}
                </div>
                <div>Buyer: {order.buyer_name}</div>
                <div>Total: ${parseFloat(order.total).toFixed(2)}</div>
                <div>
                  <strong>Shipping:</strong> {shipping.address1}, {shipping.city}, {shipping.state} {shipping.zip}
                </div>
                <ul>
                  {items.map((item, i) => (
                    <li key={i}>
                      Listing #{item.listing_id} – ${parseFloat(item.price).toFixed(2)}<br />
                      <span style={{ fontStyle: "italic", fontSize: "14px" }}>
                        Seller: {getSellerUsername(item.user_id)}
                      </span>
                    </li>
                  ))}
                </ul>
                <button className="cancel-btn" onClick={() => cancelOrder(order.id)}>
                  Cancel Order
                </button>
              </div>
            );
          })
        )}
      </div>
      <Footer />
    </div>
  );
};

// Export component for use in other parts of the application
export default MyOrders;
